import numpy as np

def problem(x: np.ndarray) -> float:
    """
    Synthetic benchmark function designed to match specific ELA features.
    """
    x1, x2 = x
    return (
        0.7 * (x1**2 + 2*x2**2 + x1*x2 + 0.2*x1**3) +
        0.3 * np.cos(10 * x1) * np.sin(10 * x2) + 0.1 * x1 + 0.01 * x2 + 0.2
    )
